tool.command:
export PANEX_PATH=/usr/local/bin/PanExplorer_workflow;

#if str($mode.mode) == "accessions":
	    perl ${__tool_directory__}/generateConfig.pl 'None' '$input' config.yaml 'None';
#else if str($mode.mode) == "genbanks":
	    perl ${__tool_directory__}/generateConfig.pl '$private_genomes' 'None' config.yaml 'None';
#else if str($mode.mode) == "fasta":
            perl ${__tool_directory__}/generateConfig.pl '$private_genomes' 'None' config.yaml '$private_genomes_fasta';
#end if


touch $vcf;
touch $vntr_matrix;
touch $gfa_file;
touch $coregenes_alignment;

cat config.yaml >>$logfile;

#if $software=="pgap"
    /usr/local/bioinfo/singularity-4.0.1/bin/singularity exec ${__tool_directory__}/panexplorer_workflow_v2.sif snakemake --cores 1 --config identity=$min_identity -s \$PANEX_PATH/Snakemake_files/Snakefile_wget_PGAP_heatmap_upset_COG >>$logfile 2>&1;
#else if $software=="roary" and $generate_core_genes_alignment=="true"
    /usr/local/bioinfo/singularity-4.0.1/bin/singularity exec ${__tool_directory__}/panexplorer_workflow_v2.sif snakemake --cores 1 --config identity=$min_identity generate_core_genes_alignment=True -s \$PANEX_PATH/Snakemake_files/Snakefile_wget_roary_heatmap_upset_COG >>$logfile 2>&1;
#else if $software=="roary"
    /usr/local/bioinfo/singularity-4.0.1/bin/singularity exec ${__tool_directory__}/panexplorer_workflow_v2.sif snakemake --cores 1 --config identity=$min_identity generate_core_genes_alignment=False -s \$PANEX_PATH/Snakemake_files/Snakefile_wget_roary_heatmap_upset_COG >>$logfile 2>&1;
#else if $software=="orthofinder"
    /usr/local/bioinfo/singularity-4.0.1/bin/singularity exec ${__tool_directory__}/panexplorer_workflow_v2.sif snakemake --cores 1 --config identity=$min_identity -s \$PANEX_PATH/Snakemake_files/Snakefile_orthofinder_heatmap_upset >>$logfile 2>&1;
#else if $software=="cactus"
    /usr/local/bioinfo/singularity-4.0.1/bin/singularity exec ${__tool_directory__}/panexplorer_workflow_v2.sif snakemake --cores 1 --config identity=$min_identity -s \$PANEX_PATH/Snakemake_files/Snakefile_wget_cactus_heatmap_upset_COG2 >>$logfile 2>&1;
#else if $software=="pggb" and str($mode.mode) == "fasta"
	    /usr/local/bioinfo/singularity-4.0.1/bin/singularity exec ${__tool_directory__}/panexplorer_workflow_v2.sif snakemake --cores 1 --config identity=$min_identity -s \$PANEX_PATH/Snakemake_files/Snakefile_pggb_heatmap_upset_COG >>$logfile 2>&1;cat outputs/*matrix.tsv >>$outcog_stat2;
#else if $software=="pggb"
    #if str($mode.mode) == "fasta"
	    /usr/local/bioinfo/singularity-4.0.1/bin/singularity exec ${__tool_directory__}/panexplorer_workflow_v2.sif snakemake --cores 1 --config identity=$min_identity -s \$PANEX_PATH/Snakemake_files/Snakefile_pggb_heatmap_upset_COG >>$logfile 2>&1;

    #else
	    /usr/local/bioinfo/singularity-4.0.1/bin/singularity exec ${__tool_directory__}/panexplorer_workflow_v2.sif snakemake --cores 1 --config identity=$min_identity -s \$PANEX_PATH/Snakemake_files/Snakefile_wget_pggb_heatmap_upset_COG >>$logfile 2>&1;
    #end if
#else
    /usr/local/bioinfo/singularity-4.0.1/bin/singularity exec ${__tool_directory__}/panexplorer_workflow_v2.sif snakemake --cores 1 --config identity=$min_identity -s \$PANEX_PATH/Snakemake_files/Snakefile_wget_panacota_heatmap_upset_COG >>$logfile 2>&1;
#end if
